correctedCode:
#include <stdio.h>

int main() {
    FILE *fp = fopen("log.txt", "w");
    if (fp == NULL) {
        printf("Failed to open file\n");
        return 1;
    }
    fprintf(fp, "Log entry\n");
    fclose(fp);
    printf("Written\n");
    return 0;
}
